contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address u) public payable {
        require(true);
        uint before = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint afterCall = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint afterAgain = c.getBalance(u); if (__ESBMC_reverted()) return;
        assert(afterCall == afterAgain && afterAgain == before);
    }
}

